import {controller} from '@github/catalyst'

type FilterState = 'included' | 'excluded'

// This interface is meant to match both select-panel and select-panel-experimental
type SelectPanelLike = {
  items: Element[]
  isItemChecked(item: Element): boolean
}

@controller('actions-workflow-filter-panel')
class ActionsWorkflowFilterPanelElement extends HTMLElement {
  // Tracks the current state of each value: included, excluded, or absent (not in map)
  #selections: Map<string, FilterState> = new Map()
  #lastClickWasAlt = false
  #updatingLabels = false
  #observer: MutationObserver | null = null
  #abortController: AbortController | null = null
  #initialIncluded: Set<string> = new Set()
  #initialExcluded: Set<string> = new Set()

  /** Returns whichever SelectPanel variant is rendered inside this element. */
  get #selectPanel(): Element | null {
    return this.querySelector('select-panel, select-panel-experimental')
  }

  connectedCallback() {
    this.#abortController?.abort()
    this.#abortController = new AbortController()
    const {signal} = this.#abortController

    this.addEventListener('panelClosed', this.#handlePanelClosed, {signal})
    this.addEventListener('beforeItemActivated', this.#handleBeforeItemActivated, {signal})
    this.addEventListener('click', this.#captureAltClick, {capture: true, signal})
    this.addEventListener('keydown', this.#captureAltClick, {capture: true, signal})
    this.addEventListener('itemActivated', this.#updateExcludedLabels, {signal})

    this.#observer = new MutationObserver(() => this.#updateExcludedLabels())
    this.#observer.observe(this, {childList: true, subtree: true})

    // Initialize from server-rendered data attributes (JSON arrays)
    this.#selections.clear()
    this.#initialIncluded = new Set(JSON.parse(this.getAttribute('data-included-values') || '[]') as string[])
    this.#initialExcluded = new Set(JSON.parse(this.getAttribute('data-excluded-values') || '[]') as string[])

    for (const v of this.#initialIncluded) {
      this.#selections.set(v, 'included')
    }
    for (const v of this.#initialExcluded) {
      this.#selections.set(v, 'excluded')
    }

    this.#updateExcludedLabels()
  }

  disconnectedCallback() {
    this.#abortController?.abort()
    this.#abortController = null
    this.#observer?.disconnect()
    this.#observer = null
  }

  // Capture alt/option modifier from both mouse clicks and keyboard activation (Enter/Space)
  #captureAltClick = (event: Event) => {
    if (event instanceof MouseEvent || event instanceof KeyboardEvent) {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      this.#lastClickWasAlt = event.altKey
    }
  }

  #handleBeforeItemActivated = (event: Event) => {
    const detail = (event as CustomEvent).detail
    if (!detail) return

    // This logic is to support both select-panel and select-panel-experimental
    const item = detail.item as Element | null
    const value =
      (detail.value as string | null) ||
      item?.getAttribute('data-value') ||
      item?.querySelector('.ActionListContent')?.getAttribute('data-value')
    if (!value) return

    const current = this.#selections.get(value)
    const isAlt = this.#lastClickWasAlt
    this.#lastClickWasAlt = false

    switch (current) {
      case 'excluded':
        if (isAlt) {
          // Alt-click excluded → neutral
          event.preventDefault()
          this.#selections.delete(value)
          this.#updateExcludedLabels()
        } else {
          // Click excluded → included
          this.#selections.set(value, 'included')
          this.#updateExcludedLabels()
        }
        break

      case 'included':
        if (isAlt) {
          // Alt-click included → excluded: let SelectPanel uncheck the item
          // naturally (it toggles checked→unchecked) so its internal state,
          // hidden inputs, and invoker label stay in sync. The itemActivated
          // event will trigger a label update afterward.
          this.#selections.set(value, 'excluded')
        } else {
          // Click included → neutral (let SelectPanel uncheck)
          this.#selections.delete(value)
        }
        break

      default:
        if (isAlt) {
          // Alt-click neutral → excluded
          event.preventDefault()
          this.#selections.set(value, 'excluded')
          this.#updateExcludedLabels()
        } else {
          // Click neutral → included (let SelectPanel check)
          this.#selections.set(value, 'included')
        }
        break
    }
  }

  #updateExcludedLabels = () => {
    if (this.#updatingLabels) return
    this.#updatingLabels = true

    const selectPanel = this.#selectPanel
    if (!selectPanel) {
      this.#updatingLabels = false
      return
    }

    // Iterate the <li> items via the SelectPanel items getter, which works
    // for both select-panel and select-panel-experimental.
    const panel = selectPanel as unknown as SelectPanelLike
    for (const item of panel.items) {
      // data-value lives on .ActionListContent in stable, on <li> in experimental
      const value =
        item.getAttribute('data-value') || item.querySelector('.ActionListContent')?.getAttribute('data-value')
      if (!value) continue

      const isExcluded = this.#selections.get(value) === 'excluded'
      const existingIcon = item.querySelector('.wrf-excluded-icon')

      if (isExcluded) {
        const label = item.querySelector('.ActionListItem-label')?.textContent?.trim() || value
        item.setAttribute('aria-label', `Excluded: ${label}`)
        if (!existingIcon) {
          // Hide any existing trailing visual (the "Default" branch label) to avoid overlap
          const content = item.querySelector('.ActionListContent')
          for (const el of content?.querySelectorAll('.ActionListItem-visual--trailing') ?? []) {
            ;(el as HTMLElement).hidden = true
          }
          content?.appendChild(this.#createExcludedIcon())
        }
      } else {
        item.removeAttribute('aria-label')
        if (existingIcon) {
          // Restore trailing visual
          const content = existingIcon.closest('.ActionListContent')
          existingIcon.remove()
          for (const el of content?.querySelectorAll('.ActionListItem-visual--trailing[hidden]') ?? []) {
            ;(el as HTMLElement).hidden = false
          }
        }
      }
    }

    this.#updatingLabels = false
  }

  // Circle slash icon from https://primer.style/octicons/circle-slash-16
  #createExcludedIcon(): HTMLSpanElement {
    const span = document.createElement('span')
    span.className = 'wrf-excluded-icon ActionListItem-visual ActionListItem-visual--trailing color-fg-muted'
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
    svg.setAttribute('aria-hidden', 'true')
    svg.setAttribute('height', '16')
    svg.setAttribute('viewBox', '0 0 16 16')
    svg.setAttribute('width', '16')
    svg.classList.add('octicon', 'octicon-circle-slash')
    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path')
    path.setAttribute(
      'd',
      'M8 0a8 8 0 1 1 0 16A8 8 0 0 1 8 0ZM3.965 13.096a6.5 6.5 0 0 0 9.131-9.131ZM1.5 8a6.474 6.474 0 0 0 1.404 4.035l9.131-9.131A6.499 6.499 0 0 0 1.5 8Z',
    )
    svg.appendChild(path)
    span.appendChild(svg)
    return span
  }

  #handlePanelClosed = () => {
    const filterKey = this.getAttribute('data-filter-key')
    const basePath = this.getAttribute('data-base-path')
    const selectPanel = this.#selectPanel
    if (!selectPanel || !filterKey || basePath == null) return

    // Build current included/excluded from our authoritative state
    const included = new Set<string>()
    const excluded = new Set<string>()
    for (const [value, state] of this.#selections) {
      if (state === 'included') included.add(value)
      else if (state === 'excluded') excluded.add(value)
    }

    // Also include any items the user checked via SelectPanel that we haven't tracked.
    // Use the isItemChecked API (handles aria-selected vs aria-checked for select variant).
    const panel = selectPanel as unknown as SelectPanelLike
    for (const item of panel.items) {
      if (!panel.isItemChecked(item)) continue
      const value =
        item.getAttribute('data-value') || item.querySelector('.ActionListContent')?.getAttribute('data-value')
      if (value && !excluded.has(value)) included.add(value)
    }

    // Skip navigation if nothing changed
    if (this.#setsEqual(included, this.#initialIncluded) && this.#setsEqual(excluded, this.#initialExcluded)) {
      return
    }

    const qualifiers: string[] = []
    for (const v of included) qualifiers.push(`${filterKey}:${this.#encodeValue(v)}`)
    for (const v of excluded) qualifiers.push(`-${filterKey}:${this.#encodeValue(v)}`)

    if (qualifiers.length === 0) {
      this.#safeNavigate(basePath)
      return
    }

    const encoded = qualifiers.map(q => encodeURIComponent(q)).join('+')

    if (basePath.includes('query=')) {
      this.#safeNavigate(basePath.replace(/(query=)([^&]*)/, `$1$2+${encoded}`))
    } else {
      const separator = basePath.includes('?') ? '&' : '?'
      this.#safeNavigate(`${basePath}${separator}query=${encoded}`)
    }
  }

  // Navigate safely by validating the URL is same-origin
  #safeNavigate(url: string) {
    const parsed = new URL(url, window.location.origin)
    if (parsed.origin === window.location.origin) {
      window.location.href = parsed.href
    }
  }

  // Quote values containing spaces or quotes to match Search::ParsedQuery.encode_value
  #encodeValue(value: string): string {
    if (/[\s"\\]/.test(value)) {
      return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`
    }
    return value
  }

  #setsEqual(a: Set<string>, b: Set<string>): boolean {
    if (a.size !== b.size) return false
    for (const v of a) {
      if (!b.has(v)) return false
    }
    return true
  }
}
